// [WSCoop] A message is on screen until the switcher is back at index 0: newer messages queue behind
// it instead of replacing it at once (server announcements vanished under the next popup).
if (ActiveIndex != 0)
    return;

// [WSCoop] Coop notices stay up longer: they are sentences, not titles.
if (Request.Payload.Contains(FWSNoticePayload))
{
    System::ClearAndInvalidateTimerHandle(ClearTimerHandle);
    ClearTimerHandle = System::SetTimer(this, n"Clear", 5.5, false);
}

// [WSCoop] Coop notices borrow the quest banner with their own title; real quest updates get "New Quest" back.
UWSNoticeState NoticeState = UWSNoticeState::Get();
if (NoticeState != nullptr && !NoticeState.bQuestTitleSaved)
{
    NoticeState.QuestTitle = Widget_NewQuest.Text_Title.WSGetText();
    NoticeState.bQuestTitleSaved = true;
}
if (Request.Payload.Contains(FWSNoticePayload))
{
    const auto& Notice = Request.Payload.Get(FWSNoticePayload);
    Widget_NewQuest.SetTitle(Notice.Title);
    Widget_NewQuest.SetInfo(Notice.Info);
    Widget_NewQuest.SetPatternType(EUnlockMessagePatternType::Purple);
    return Widget_NewQuest.GetParent();
}
if (NoticeState != nullptr && NoticeState.bQuestTitleSaved)
    Widget_NewQuest.SetTitle(NoticeState.QuestTitle);

// [WSCoop] Already at index 0 (nothing was shown): no change event follows, so move the queue on here.
if (WidgetSwitcher.GetActiveWidgetIndex() == 0)
{
    TryConsumeFromQueue();
    return;
}
